window.BUILDS=[{"id":"P01","name":"Crayon Crew","ages":"5–9","mins":10,"goal":"Give your crayons a tidy home.","start":"Yoghurt pot","materials":[{"name":"Clean yoghurt pot","qty":"1"},{"name":"Scrap-paper strip","qty":"Optional"},{"name":"Short crayons already owned","qty":"A few"},{"name":"Scissors","qty":"Grown-up only"}],"suit":"Use an empty, clean, dry yoghurt pot with a broad base and smooth, unbroken rim. Remove the foil lid completely. Choose short crayons that stick out above the rim. Do not use tiny broken crayons, long pencils or sharp tools.","prep":"Wash, dry and check the pot. Keep scissors with the grown-up. Check the filled pot stands steadily.","steps":[{"n":1,"title":"Check your pot","text":"Ask a grown-up to wash, dry and check your pot.","grownup":true,"optional":false,"fig":"P01-08"},{"n":2,"title":"Make a picture label","text":"Want a label? Draw a picture on your paper strip.","grownup":false,"optional":true,"fig":"P01-09"},{"n":3,"title":"Wrap the label","text":"If you made a label, wrap it around the pot.","grownup":false,"optional":true,"fig":"P01-10"},{"n":4,"title":"Move your crayons in","text":"Put a few short crayons inside. Can your pot stay standing?","grownup":false,"optional":false,"fig":"P01-11"}],"status":"live","edited":"last edited by Tom Ellis","since":"2 November"},{"id":"P02","name":"Our Tomorrow Town","ages":"5–9","mins":20,"goal":"Make a play town where people borrow and mend.","start":"Clean brown packing paper","materials":[{"name":"Clean brown packing paper","qty":"1 sheet that fits on the table","optional":false,"grownup":false},{"name":"Crayons or pencil already owned","qty":"Enough to draw your map","optional":false,"grownup":false},{"name":"Existing small-world toys","qty":"2 or 3 intact toys","optional":false,"grownup":false}],"suit":"Use clean, dry, plain packing paper that is no longer needed for packing. It must have no staples, sticky residue or plastic coating and fit fully on the table. Choose existing age-appropriate toys with no loose small parts.","prep":"Check the paper and choose a sheet that fits a dry tabletop; a larger sheet can stay folded to fit. Keep paper off the floor and away from food. Help name the library and repair place. Ask the child where a toy could borrow a book, without giving the answer first. Keep the finished map with the toys for future play.","steps":[{"n":1,"title":"Open your map","text":"Smooth your paper on the table. Its old creases can stay.","grownup":false,"optional":false,"fig":"P02-06"},{"n":2,"title":"Draw helpful places","text":"Draw a home, a library for borrowing books and a place where grown-ups mend things.","grownup":false,"optional":false,"fig":"P02-07"},{"n":3,"title":"Take a toy journey","text":"Your toy needs a book. Move it from home to somewhere it can borrow one.","grownup":false,"optional":false,"fig":"P02-08"},{"n":4,"title":"Save the town","text":"Fold your town along its creases. Keep it with your toys for your next adventure.","grownup":false,"optional":false,"fig":"P02-09"}],"status":"live"},{"id":"P03","name":"Puzzle Rescue","ages":"7–9","mins":25,"goal":"Help your favourite puzzle stay in play.","start":"Large-piece jigsaw missing one","materials":[{"name":"Existing large-piece puzzle","qty":"1 family-owned puzzle with one missing piece","optional":false,"grownup":false},{"name":"Suitable scrap card","qty":"1 piece larger than the gap, close to the puzzle thickness","optional":false,"grownup":false},{"name":"Pencil and crayons already owned","qty":"1 pencil and colours for the missing picture","optional":false,"grownup":false},{"name":"Suitable scissors for the grown-up","qty":"1 pair that cuts the card easily","optional":false,"grownup":true}],"suit":"Choose a family-owned large-piece cardboard puzzle with one missing piece and all other pieces intact. The missing shape must be large and simple. Use scrap card close to the original thickness that an adult can cut with scissors. Do not alter borrowed, library or valuable puzzles.","prep":"Check the replacement will remain a large piece and the card cuts easily with scissors; do not use a knife. Assemble the puzzle and steady it while the child traces onto card beneath the gap. Cut from the card edge to the outline, then follow it. Remove offcuts. Check edges and gently trial the fit: it must sit flat and lift out without force. Trim small amounts yourself if needed. Keep the replacement with the puzzle. If no workable fit is achievable, ask the maker about a replacement.","steps":[{"n":1,"title":"Trace the gap","text":"Ask your grown-up to steady the puzzle. Put card underneath the gap and trace around it.","grownup":false,"optional":false,"fig":"P03-07"},{"n":2,"title":"Grown-up cuts","text":"Your grown-up cuts along your outline, then checks the edges and fit.","grownup":true,"optional":false,"fig":"P03-08"},{"n":3,"title":"Complete the picture","text":"Look at the picture around the gap. Draw the missing part on your new piece.","grownup":false,"optional":false,"fig":"P03-09"},{"n":4,"title":"Try the fit","text":"Place your piece gently in the gap. Check it sits flat and lifts out easily. Ask your grown-up for a trim if needed.","grownup":false,"optional":false,"fig":"P03-10"}],"status":"live"},{"id":"P04","name":"Small-World Story Stage","ages":"5–9","mins":15,"goal":"Tell a story about sharing what we already have.","start":"Empty shoebox with lid","materials":[{"name":"Clean shoebox and lid","qty":"1 set","optional":false,"grownup":false},{"name":"Existing intact toy figures","qty":"2 toys","optional":false,"grownup":false},{"name":"Existing drawing for scenery","qty":"1 that fits inside the box","optional":true,"grownup":false}],"suit":"Use a small, clean, dry shoebox and lid that are no longer needed for another job. Check for staples, sharp fasteners, strong smells or residue. Choose two intact, age-appropriate toys that fit comfortably inside.","prep":"Check the box, lid and toys. Stand the box on its broad, long side on a steady table, with the opening facing the child. Check it will not tip during gentle play; if it tips, lay it flat as an open scene instead. An existing drawing may rest inside as scenery without glue. Keep the box intact so it can return to storage use.","steps":[{"n":1,"title":"Set the stage","text":"With your grown-up, stand the box on its broad side. Point the opening towards you.","grownup":true,"optional":false,"fig":"P04-06"},{"n":2,"title":"Choose your cast","text":"Choose two toys you already own. Decide who they will be in your story.","grownup":false,"optional":false,"fig":"P04-07"},{"n":3,"title":"Act out a choice","text":"One character needs something. Show how the other can help by lending or sharing.","grownup":false,"optional":false,"fig":"P04-08"},{"n":4,"title":"Pack it for tomorrow","text":"Lay the box flat. Put your toys and any scenery inside, then add the lid. Save your stage for another story.","grownup":false,"optional":false,"fig":"P04-09"}],"status":"live"},{"id":"P05","name":"My Drawer Designer","ages":"7–9","mins":25,"goal":"Give the things you use their own easy-to-find spaces.","start":"Cardboard packaging divider","materials":[{"name":"Existing corrugated card","qty":"Enough for 2 fitted divider strips","optional":false,"grownup":false},{"name":"Pencil already owned","qty":"1","optional":false,"grownup":false},{"name":"Ruler already owned","qty":"1 long enough to measure the drawer","optional":false,"grownup":false},{"name":"Suitable scissors for the grown-up","qty":"1 pair that cuts the card easily","optional":false,"grownup":true},{"name":"Stationery already needing a home","qty":"A small selection of light items","optional":false,"grownup":false},{"name":"Scrap paper for the plan","qty":"1 small piece with a blank side","optional":false,"grownup":false},{"name":"Existing shallow drawer","qty":"1 approved by a grown-up","optional":false,"grownup":false}],"suit":"Use clean, dry, uncoated packaging card without staples. It must be firm enough to stand but easy for a grown-up to cut with scissors. Choose an adult-approved shallow drawer for light stationery, never medicines, sharp tools or other unsuitable items.","prep":"Empty the drawer. Measure its inside width, depth and clear height. Cut two strips: one just shorter than the width, one just shorter than the depth. Both must have equal height, below drawer clearance. At each strip’s lengthwise midpoint, cut a slot exactly halfway through its height: down from the top on one, up from the bottom on the other. Each slot must match the other strip’s thickness. Test the cross fits without force and the drawer closes freely. Remove offcuts; supervise fingers near the drawer.","steps":[{"n":1,"title":"Plan the spaces","text":"Choose the things that need a home. Draw a four-space plan on scrap paper with your grown-up.","grownup":false,"optional":false,"fig":"P05-08"},{"n":2,"title":"Ask for fitted strips","text":"Your grown-up measures the drawer and cuts two strips with matching halfway slots: one from the top, one from the bottom.","grownup":true,"optional":false,"fig":"P05-09"},{"n":3,"title":"Slide them together","text":"Slide the slots together to make a cross. Lower it into the empty drawer without forcing it.","grownup":false,"optional":false,"fig":"P05-10"},{"n":4,"title":"Give things a home","text":"Put your things in their spaces. Find the thing you use most, then check the drawer closes gently with your grown-up.","grownup":false,"optional":false,"fig":"P05-11"}],"status":"live"},{"id":"P06","name":"One-at-a-Time Cloth Station","ages":"5–9","mins":12,"goal":"Keep clean cloths ready for everyday spills.","start":"Empty tissue box","materials":[{"name":"Empty prepared tissue box","qty":"1","optional":false,"grownup":false},{"name":"Clean, dry reusable cloths already owned","qty":"3 small cloths that fit loosely","optional":false,"grownup":false},{"name":"Scissors for the grown-up","qty":"1 pair, only if the opening needs trimming","optional":true,"grownup":true}],"suit":"Use a clean, dry, intact tissue box and clean, dry reusable cloths already owned. Do not collect used tissues or cut useful towels. The opening must be broad and smooth enough for a loosely folded cloth to pass through without snagging.","prep":"Remove all plastic film and loose scraps from the opening. Check the edge is smooth; if needed, trim only the opening with scissors, keeping the box sturdy. Choose another existing box if a safe, broad opening is not possible. Keep the station in a dry place, away from sinks and food preparation. Show where used cloths go for washing. Only clean, fully dry cloths return to the box; stop using the box if it becomes damp or dirty.","steps":[{"n":1,"title":"Check the opening","text":"Ask your grown-up to remove any plastic film and check the box has a smooth, wide opening.","grownup":true,"optional":false,"fig":"P06-05"},{"n":2,"title":"Try a fold","text":"Fold each clean, dry cloth into a small rectangle that fits loosely through the opening.","grownup":false,"optional":false,"fig":"P06-06"},{"n":3,"title":"Stack them gently","text":"Stack the folded cloths inside. Leave room to pick up the top one.","grownup":false,"optional":false,"fig":"P06-07"},{"n":4,"title":"Try one at a time","text":"Lift out one cloth gently. If several come out, try smaller folds. Keep your station ready for the next spill.","grownup":false,"optional":false,"fig":"P06-08"}],"status":"live"},{"id":"P07","name":"Desk Post","ages":"5–9","mins":15,"goal":"Keep your favourite drawings easy to find.","start":"Empty cereal box","materials":[{"name":"Empty cereal box","qty":"1 with an intact base","optional":false,"grownup":false},{"name":"Pencil or crayon already owned","qty":"1 for marking the cut lines and drawing the sign","optional":false,"grownup":false},{"name":"Scissors for the grown-up","qty":"1 suitable pair","optional":false,"grownup":true},{"name":"Drawings or letters to store","qty":"2 or 3 lightweight sheets that fit","optional":false,"grownup":false}],"suit":"Use an empty, clean, dry cereal box with an intact, firmly closed base and no food residue, damp, mould or staples. Choose a box wide enough for the papers you already need to store. Use only a few lightweight sheets.","prep":"Remove the inner bag. With the box upright, remove the top flaps. Mark the front halfway up; keep the back at full height. Draw a slope on each narrow side from the lower front to the top back. Cut along these lines with scissors, leaving the base and lower corners intact. Check cut edges. Test with the intended papers; use fewer sheets or another existing, steadier box if it tips. Keep it on a dry, reachable surface away from the edge.","steps":[{"n":1,"title":"Prepare the opening","text":"Your grown-up cuts the front lower than the back, with sloping sides. The bottom stays closed.","grownup":true,"optional":false,"fig":"P07-07"},{"n":2,"title":"Give it a sign","text":"Draw a picture on the front to show what belongs inside.","grownup":false,"optional":false,"fig":"P07-08"},{"n":3,"title":"Post your papers","text":"Slide in a few drawings. Put the one you want to find first at the front.","grownup":false,"optional":false,"fig":"P07-09"},{"n":4,"title":"Choose its home","text":"Put your Desk Post on a steady, reachable desk or shelf. Take out one drawing gently: does the box stay standing?","grownup":false,"optional":false,"fig":"P07-10"}],"status":"live"},{"id":"P08","name":"Fold-Out Adventure Book","ages":"5–9","mins":15,"goal":"Give used paper a new story about caring for things.","start":"Paper printed on one side","materials":[{"name":"Used paper with a blank side","qty":"1 sheet","optional":false,"grownup":false},{"name":"Crayons or pencil already owned","qty":"Enough to draw four pictures","optional":false,"grownup":false}],"suit":"Use one clean, dry sheet with a blank side and no staples. A grown-up must check that nobody needs the document and that the printed side contains no private or unsuitable information. Do not cover the printed side with new paper.","prep":"Use a landscape sheet. Fold it in half across its width. With it still folded, fold each loose short edge back to the first fold, turning it over to reach the second edge. Open out: the three creases alternate direction to make four equal concertina panels. Help with folds, especially for ages 5–6. Open the blank side upwards for drawing. No cutting, binding, glue or cover is needed.","steps":[{"n":1,"title":"Fold four panels","text":"With help, fold your paper into four equal panels, backwards and forwards like a zigzag.","grownup":false,"optional":false,"fig":"P08-05"},{"n":2,"title":"Meet your character","text":"Open the blank side upwards. Draw your character in the first panel.","grownup":false,"optional":false,"fig":"P08-06"},{"n":3,"title":"Tell a clever story","text":"Use the next three panels: a book needs mending, a grown-up helps, and your character enjoys the book again.","grownup":false,"optional":false,"fig":"P08-07"},{"n":4,"title":"Open and tell","text":"Fold your book closed. Open one panel at a time and tell someone how your character kept the book in use.","grownup":false,"optional":false,"fig":"P08-08"}],"status":"live"},{"id":"P09","name":"Gift Hug","ages":"5–9","mins":10,"goal":"Wrap a gift in cloth that can be used again.","start":"Spare scarf","materials":[{"name":"Spare short scarf or tea towel","qty":"1 roughly square cloth that fits the gift","optional":false,"grownup":false},{"name":"Book or gift already being given","qty":"1 suitably sized item","optional":false,"grownup":false}],"suit":"Choose a clean, spare, roughly square short scarf or tea towel, without loose trims. It must wrap the existing gift without stretching or leaving long trailing ends. Use a gift already being given; do not buy one for this activity or take cloth needed for another job.","prep":"Check the cloth and gift size. Keep cloth on the table and away from faces and necks. Cross the remaining corners, pass one end underneath and pull gently into one loose overhand knot. Keep it easy to undo; do not add ribbons, pins or tape. Help the child check the knot can be loosened. Carry the gift from underneath. Agree that the recipient will reuse the cloth or return it for another gift.","steps":[{"n":1,"title":"Place the gift","text":"Lay your cloth flat like a diamond. Put your gift in the middle.","grownup":false,"optional":false,"fig":"P09-05"},{"n":2,"title":"Fold two corners","text":"Fold two opposite corners over the gift.","grownup":false,"optional":false,"fig":"P09-06"},{"n":3,"title":"Meet the ends","text":"Bring the other two corners together above the gift.","grownup":false,"optional":false,"fig":"P09-07"},{"n":4,"title":"Make a gentle knot","text":"Ask your grown-up to help tie one loose knot. Check it is easy to undo, so the cloth can wrap another gift.","grownup":true,"optional":false,"fig":"P09-08"}],"status":"live"},{"id":"P10","name":"Brick Drying Bay","ages":"5–9","mins":10,"goal":"Care for your toy bricks so they are ready for play.","start":"Rigid fruit punnet","materials":[{"name":"Clean rigid fruit punnet","qty":"1 with smooth existing ventilation holes","optional":false,"grownup":false},{"name":"Existing clean towel","qty":"1, folded beneath the punnet","optional":false,"grownup":false},{"name":"Existing washable toy bricks","qty":"A few large, non-electrical bricks needing cleaning","optional":false,"grownup":false}],"suit":"Use a clean, rigid fruit punnet with existing ventilation holes, no cracks and no sharp edges. Remove film and loose labels. Choose large, intact, non-electrical toy bricks that need cleaning and whose maker permits washing. Exclude battery parts, magnets, stickers and small loose pieces.","prep":"Wash and dry the punnet; check the rim and ventilation holes. Do not cut new holes. Wash suitable bricks only as their maker directs, using permitted water temperature and cleaning products; the grown-up handles cleaning. Use a stable surface away from sockets and electronics. Spread bricks in one layer with gaps, turning cavities down so water can drain. Check all surfaces and hollows are fully dry before returning them to storage. Dry the punnet and towel afterwards.","steps":[{"n":1,"title":"Let a grown-up check","text":"Ask a grown-up to check the punnet and wash only toy bricks that their maker says can be washed.","grownup":true,"optional":false,"fig":"P10-06"},{"n":2,"title":"Make a dry base","text":"Fold your clean towel and put the punnet on top.","grownup":false,"optional":false,"fig":"P10-07"},{"n":3,"title":"Give each brick space","text":"Place the washed bricks in one layer with gaps. Turn hollow sides down so water can drain.","grownup":false,"optional":false,"fig":"P10-08"},{"n":4,"title":"Return them when dry","text":"Wait until your grown-up checks the bricks are fully dry. Put them back with their set, ready to play again.","grownup":false,"optional":false,"fig":"P10-09"}],"status":"live"},{"id":"P11","name":"Desk Roll","ages":"5–9","mins":8,"goal":"Keep a favourite drawing ready to use again.","start":"Empty kitchen roll tube","materials":[{"name":"Kitchen roll tube","qty":"1","optional":false,"grownup":false},{"name":"Existing dry drawing","qty":"1","optional":false,"grownup":false},{"name":"Pencil or crayon","qty":"1 already owned","optional":false,"grownup":false}],"suit":"Use a clean, dry, intact kitchen roll tube with no food or cleaning-product residue. Choose an existing drawing with fully dry paint or glue. It must roll gently and fit loosely inside the uncut tube. If it does not, keep the drawing flat instead.","prep":"Check that the drawing belongs to the child and can be rolled without damage. Do not use delicate, brittle or valuable artwork. Help make a loose roll without creases and check that the tube slides on and off freely. Do not cut the tube or roll the drawing tighter to force a fit. Choose a dry art drawer for storage.","steps":[{"n":1,"title":"Roll gently","text":"Gently roll your dry drawing into a loose tube. Keep the picture facing out. Do not fold or crease it.","grownup":false,"optional":false,"fig":"P11-06"},{"n":2,"title":"Slide on the sleeve","text":"Slide the kitchen roll tube over your drawing. Stop if it feels tight and ask your grown-up for help.","grownup":false,"optional":false,"fig":"P11-07"},{"n":3,"title":"Make a picture clue","text":"Draw a little clue on the cardboard so you remember which drawing is inside.","grownup":false,"optional":false,"fig":"P11-08"},{"n":4,"title":"Park your drawing","text":"Check your drawing slides out easily, then slide it back in. Lay your Desk Roll in the art drawer.","grownup":false,"optional":false,"fig":"P11-09"}],"status":"live"},{"id":"P12","name":"Dust Buddy","ages":"5–9","mins":7,"goal":"Give an unneeded sock a useful dusting job.","start":"Clean single sock","materials":[{"name":"Clean single sock","qty":"1","optional":false,"grownup":false}],"suit":"Choose a clean, dry, unpaired sock that is no longer needed as clothing. It must fit loosely over the child's hand, without holes that catch fingers, loose threads or decorations. Use only a low, stable, empty shelf that can be dry-dusted.","prep":"Check that the child can remove the sock easily. Empty a low shelf within easy reach, away from plugs, sockets and electrical equipment. Remove chemicals, sharp objects and fragile items. No climbing, cleaning spray or liquid is needed. Show the child where to put the sock for washing. Add it to the usual suitable laundry load, then dry it before its next dusting job.","steps":[{"n":1,"title":"Meet your buddy","text":"Slide your hand into the sock. Keep your fingers comfortable. Ask for help if it feels tight.","grownup":false,"optional":false,"fig":"P12-04"},{"n":2,"title":"Pick a patch","text":"Ask your grown-up to show you one low, empty shelf to dust. Keep both feet on the floor.","grownup":true,"optional":false,"fig":"P12-05"},{"n":3,"title":"Sweep gently","text":"Move your sock slowly across the shelf, from one side to the other. Watch the dust collect on your sock.","grownup":false,"optional":false,"fig":"P12-06"},{"n":4,"title":"Off to wash","text":"Can you spot less dust? Take off the sock and put it in your grown-up's washing place, ready to wash and reuse.","grownup":false,"optional":false,"fig":"P12-07"}],"status":"live"},{"id":"P13","name":"Page Pal","ages":"5–9","mins":10,"goal":"Make a bookmark for a book you are reading.","start":"Unwanted paper greeting card","materials":[{"name":"Unwanted plain greeting card","qty":"1","optional":false,"grownup":false},{"name":"Pencil","qty":"1 already owned","optional":false,"grownup":false},{"name":"Scissors for your grown-up","qty":"1 pair","optional":false,"grownup":true},{"name":"Book you are reading","qty":"1","optional":false,"grownup":false}],"suit":"Use a clean, dry greeting card its owner no longer wants. Choose plain paper or thin card with a printed picture or colour, without glitter, foil, plastic coating, buttons, sound parts or batteries. There must be room for one broad, flat strip.","prep":"Confirm permission to use the card. Check it has no attachments, sharp parts or private message that should be shown in a photo. Help the child mark a broad bookmark. Do all cutting yourself, then check the edges are smooth. Keep useful leftover card only if it has a planned use; check local recycling rules for the rest.","steps":[{"n":1,"title":"Choose a favourite bit","text":"Choose a picture or colour on the card that you would like to see in your book.","grownup":false,"optional":false,"fig":"P13-07"},{"n":2,"title":"Mark one strip","text":"Draw two long lines around your favourite bit. Join the ends to make one wide bookmark shape.","grownup":false,"optional":false,"fig":"P13-08"},{"n":3,"title":"Cut with help","text":"Ask your grown-up to cut out your bookmark along the lines and check that its edges are smooth.","grownup":true,"optional":false,"fig":"P13-09"},{"n":4,"title":"Save your page","text":"Place Page Pal between your pages. Close your book gently. Open it again: did you find your page?","grownup":false,"optional":false,"fig":"P13-10"}],"status":"live"},{"id":"P14","name":"Puzzle-Piece Home","ages":"5–9","mins":10,"goal":"Give your game pieces a home you can find.","start":"Plastic tub with lid","materials":[{"name":"Clear food tub with easy-opening lid","qty":"1","optional":false,"grownup":false},{"name":"Large puzzle or game pieces","qty":"1 existing set","optional":false,"grownup":false},{"name":"Paper offcut for a label","qty":"1 that fits inside","optional":false,"grownup":false},{"name":"Pencil or crayon","qty":"1 already owned","optional":false,"grownup":false}],"suit":"Use an unwanted, clean, dry, transparent food tub with a matching lid. Both must be intact, with smooth edges. The lid must open and close easily without force or pinching. Choose existing, large, age-appropriate game pieces that fit below the rim.","prep":"Wash and dry the tub and lid. Check the child can open and close them comfortably; choose another tub if needed. Use a tub no longer needed for food storage. Choose a game with large, intact pieces suitable for the child. Provide a clean paper offcut that fits inside as a label. No glue, tape or cutting is needed.","steps":[{"n":1,"title":"Check the home","text":"Ask your grown-up to wash, dry and check the tub and lid. Try opening and closing them gently together.","grownup":true,"optional":false,"fig":"P14-07"},{"n":2,"title":"Gather this game's pieces","text":"Gather this game's pieces. With your grown-up, check that none are missing or broken.","grownup":false,"optional":false,"fig":"P14-08"},{"n":3,"title":"Draw a finding label","text":"Draw a picture on your paper offcut to show which game lives here.","grownup":false,"optional":false,"fig":"P14-09"},{"n":4,"title":"Pack and close","text":"Put your pieces and label inside. Close and reopen the lid. Take out one piece, then put it back. Can you see your label?","grownup":false,"optional":false,"fig":"P14-10"}],"status":"live"},{"id":"P15","name":"Second-Chapter Journal","ages":"5–9","mins":10,"goal":"Use spare pages to remember useful eco choices.","start":"Partly used exercise book","materials":[{"name":"Partly used exercise book","qty":"1 with blank pages left","optional":false,"grownup":false},{"name":"Pencil or crayons","qty":"Already owned","optional":false,"grownup":false}],"suit":"Use a partly used exercise book with its owner's permission. Its binding must be intact, with no exposed staples. Choose one no longer needed for its original task, with blank pages remaining. A grown-up must check existing pages for private information before any photo or sharing.","prep":"Ask the book's owner for permission and find the first usable blank page together. Keep previous work and the binding intact; do not tear out pages. Check that the child can use the book without exposing private information. Notice ordinary family actions at home or on supervised outings. Do not send children to collect rubbish or create extra items for entries.","steps":[{"n":1,"title":"Find a fresh page","text":"With permission, open your notebook at the first blank page you can use. Keep the earlier pages safely in place.","grownup":false,"optional":false,"fig":"P15-05"},{"n":2,"title":"Name your chapter","text":"Give your new chapter a name or draw its first picture.","grownup":false,"optional":false,"fig":"P15-06"},{"n":3,"title":"Spot a good choice","text":"Draw something your family repaired, reused or kept using today. Tell someone how it helped.","grownup":false,"optional":false,"fig":"P15-07"},{"n":4,"title":"Leave room for tomorrow","text":"Close your journal, keeping the next blank page ready. Open it again when you notice another useful way to reuse something.","grownup":false,"optional":false,"fig":"P15-08"}],"status":"live"},{"id":"P16","name":"Toy Care Garage","ages":"5–9","mins":15,"goal":"Care for three toys and give each a parking place.","start":"Empty delivery box","materials":[{"name":"Small delivery box","qty":"1","optional":false,"grownup":false},{"name":"Crayon or pencil","qty":"1 already owned","optional":false,"grownup":false},{"name":"Clean dry cloth","qty":"1 already owned","optional":false,"grownup":false},{"name":"Intact toy cars","qty":"3 already owned","optional":false,"grownup":false},{"name":"Scissors for your grown-up","qty":"1 pair, only if flaps need removing","optional":true,"grownup":true}],"suit":"Use a small, clean, dry delivery box with a stable, flat base that is no longer needed. It must have no exposed staples, sharp edges or loose tape. Choose three intact, age-appropriate, non-electrical toy cars already owned, light enough to fit comfortably inside.","prep":"Remove address labels, staples and loose tape before the child handles the box. Fold flaps out of the way, or use scissors yourself to remove awkward flaps; check every edge afterwards. Reject a box that remains sharp or unstable. Check all three toy cars for loose or broken parts. Provide a dry cloth and keep the activity free from sprays, water and dismantling.","steps":[{"n":1,"title":"Prepare the garage","text":"Ask your grown-up to check the box and make the opening safe and easy to reach.","grownup":true,"optional":false,"fig":"P16-07"},{"n":2,"title":"Draw parking places","text":"Draw three parking spaces on the bottom of the box: one space for each toy car.","grownup":false,"optional":false,"fig":"P16-08"},{"n":3,"title":"Give a gentle wipe","text":"Use your dry cloth to gently wipe any toy that needs it. No sprays or water are needed.","grownup":false,"optional":false,"fig":"P16-09"},{"n":4,"title":"Park and play","text":"Park one toy in each space. Play your story, then return all three toys so you can find them next time.","grownup":false,"optional":false,"fig":"P16-10"}],"status":"live"},{"id":"P17","name":"Art Keeper Rescue","ages":"5–9","mins":15,"goal":"Repair your folder so it can keep holding drawings.","start":"Cardboard folder with a small tear","materials":[{"name":"Cardboard folder with a small tear","qty":"1","optional":false,"grownup":false},{"name":"Clean paper patch","qty":"1 prepared by a grown-up","optional":false,"grownup":false},{"name":"School glue stick for paper and card","qty":"1 already owned; use a thin layer","optional":false,"grownup":true},{"name":"Scissors for your grown-up","qty":"1 pair, only if the patch needs trimming","optional":true,"grownup":true},{"name":"Existing drawings to store","qty":"A few lightweight sheets that fit","optional":false,"grownup":false}],"suit":"Use an owned, plain, uncoated cardboard folder with one small tear away from the spine or a fold. It must otherwise be sound, without mould, exposed metal or damaged fastenings. Use an existing paper offcut and a school glue stick labelled for paper and card.","prep":"Check that the tear can be patched without changing the folder's shape. Prepare a clean paper patch that overlaps every side of the tear by at least 1 cm; do any trimming yourself. Follow the glue label and apply only a thin layer. Keep the folder flat for the stated drying time. If the patch lifts or the tear grows, stop using the folder and choose another way to store the drawings.","steps":[{"n":1,"title":"Line up the tear","text":"Open your folder and lay it flat. Gently bring the torn edges together.","grownup":false,"optional":false,"fig":"P17-06"},{"n":2,"title":"Prepare the patch","text":"Ask your grown-up to spread a thin layer of school glue on your paper patch.","grownup":true,"optional":false,"fig":"P17-07"},{"n":3,"title":"Cover the tear","text":"Press the patch over the tear inside the folder. Make sure the patch reaches beyond every side of the tear.","grownup":false,"optional":false,"fig":"P17-08"},{"n":4,"title":"Let it dry","text":"When your grown-up says the patch is dry, add a few drawings. Gently open and close the folder. Does the patch hold?","grownup":true,"optional":false,"fig":"P17-09"}],"status":"live"},{"id":"P18","name":"Brush Bath","ages":"5–9","mins":5,"goal":"Reuse a cup to rinse your paintbrush.","start":"Rigid plastic cup","materials":[{"name":"Wide, rigid plastic cup","qty":"1","optional":false,"grownup":false},{"name":"Shallow tray","qty":"1 already owned","optional":false,"grownup":false},{"name":"Water","qty":"Enough to fill about one quarter of the cup","optional":false,"grownup":true},{"name":"Paintbrush","qty":"1 already owned","optional":false,"grownup":false},{"name":"Water-based paint and painting paper","qty":"For your already-planned activity","optional":false,"grownup":false},{"name":"Small pouring jug","qty":"1 already owned","optional":false,"grownup":true}],"suit":"Use a clean, intact rigid plastic cup with a wide, stable base and smooth rim, no longer needed for drinking. Reject brittle, cracked or wobbly cups. Use an existing tray and age-appropriate water-based painting supplies for an activity already planned.","prep":"Wash and check the cup. Stand it on the tray and reject it if it tips easily. Check the painting supplies' labels. Use a small jug to add water to about one quarter of the cup's height. Keep the cup away from drinks and never use it for drinking again. Supervise painting, deal with spills, and dispose of paint water according to the paint label and local instructions.","steps":[{"n":1,"title":"Check the cup","text":"Ask your grown-up to check your cup and painting supplies. This cup is for brushes, never for drinking.","grownup":true,"optional":false,"fig":"P18-08"},{"n":2,"title":"Put it on a tray","text":"Stand the cup in the middle of your tray. Check it sits flat and steady.","grownup":false,"optional":false,"fig":"P18-09"},{"n":3,"title":"Add a little water","text":"Ask your grown-up to pour in a little water, filling the cup about one quarter full.","grownup":true,"optional":false,"fig":"P18-10"},{"n":4,"title":"Rinse while you paint","text":"Gently swish your brush in the water when you change colour. Keep the cup on the tray and never drink the water.","grownup":false,"optional":false,"fig":"P18-11"}],"status":"draft"},{"id":"P19","name":"Floor Friend","ages":"5–9","mins":5,"goal":"Use an old towel to help with a real water spill.","start":"Old towel","materials":[{"name":"Clean old towel","qty":"1 whole towel; no cutting","optional":false,"grownup":false}],"suit":"Use a clean, intact old towel no longer wanted for its original job. A grown-up must identify a small, cool, plain-water spill on a clear, level floor, away from electricity. Do not create a spill. Exclude unknown, hot or dirty liquids and cleaning products.","prep":"Stay beside the child. Keep everyone off the wet patch. The child must remain on dry floor and be able to reach the small spill with their hands. Handle any unsafe or awkward spill yourself. After the child absorbs the water, dry the remaining floor and check it is safe before anyone walks there or the child leaves. Show where the towel goes for washing; wash and dry it before reuse.","steps":[{"n":1,"title":"Check together","text":"Ask your grown-up to check that this is a small, cool, plain-water spill. Stay on the dry floor.","grownup":true,"optional":false,"fig":"P19-04"},{"n":2,"title":"Fold a pad","text":"Fold the towel into a thick pad that your hands can hold.","grownup":false,"optional":false,"fig":"P19-05"},{"n":3,"title":"Press and lift","text":"Press the pad onto the water with your hands. Lift it gently. Can you see less water?","grownup":false,"optional":false,"fig":"P19-06"},{"n":4,"title":"Ready for washing","text":"Stay on dry floor while your grown-up dries the patch and checks it. Then put the towel in the washing place.","grownup":true,"optional":false,"fig":"P19-07"}],"status":"draft"},{"id":"P20","name":"Fold-Away Mess Mat","ages":"5–9","mins":7,"goal":"Keep your dry craft pieces together and save useful scraps.","start":"Finished newspaper","materials":[{"name":"Finished newspaper","qty":"2 sheets","optional":false,"grownup":false},{"name":"Paper for your planned dry activity","qty":"Existing paper or useful offcuts","optional":false,"grownup":false},{"name":"Crayon","qty":"1 already owned","optional":false,"grownup":false}],"suit":"Use two clean, dry newspaper sheets that the household has finished reading. A grown-up must check the words and pictures are suitable for the child and remove loose inserts or staples. Choose a dry craft activity and a table that newspaper ink will not mark.","prep":"Check the newspaper's content and test for ink transfer on the chosen surface. Lay the mat fully on the table, away from food, heat and electrical equipment. Choose a paper-and-crayon activity already planned; no water, paint or glue. Afterwards, help save useful scraps with a real next use. Keep the mat if clean, dry and sound. Check local council rules separately for the remaining paper and card.","steps":[{"n":1,"title":"Fold your layers","text":"Lay two newspaper sheets together and fold them in half.","grownup":false,"optional":false,"fig":"P20-05"},{"n":2,"title":"Make a work zone","text":"Place the folded mat flat on your grown-up's chosen table. Keep every edge on the table.","grownup":false,"optional":false,"fig":"P20-06"},{"n":3,"title":"Make on the mat","text":"Draw on your paper over the mat. Keep all your paper pieces on the mat while you work.","grownup":false,"optional":false,"fig":"P20-07"},{"n":4,"title":"Gather and sort","text":"Fold the mat edges inwards. Save useful scraps with your grown-up, then follow your council's rules for the rest.","grownup":false,"optional":false,"fig":"P20-08"}],"status":"live"},{"id":"P21","name":"Game-Card Keeper","ages":"5–9","mins":8,"goal":"Keep your game cards together, ready for the next game.","start":"Small plain paper envelope","materials":[{"name":"Small plain paper envelope","qty":"1","optional":false,"grownup":false},{"name":"Loose cards from one existing game","qty":"1 complete set of that game’s cards, fitting loosely","optional":false,"grownup":false},{"name":"Pencil","qty":"1","optional":false,"grownup":false},{"name":"The game’s own box","qty":"1","optional":false,"grownup":false}],"suit":"Use a clean, dry, spare paper envelope with an intact flap, no plastic window and no metal fastener. One existing game needs storage for its loose cards. All its cards must fit without bending, and the filled envelope must fit in the game box.","prep":"Check the envelope for sharp damage and remove private addresses before any photo. Check that the cards slide in and out easily. Choose another storage solution if the fit is tight. Use cards only, not small counters. Leave the flap unsealed: do not lick or glue it. Keep the game box ready for the finished keeper. Use only materials already owned.","steps":[{"n":1,"title":"Pick the cards","text":"Gather the loose cards from one game. These cards will share a home.","grownup":false,"optional":false,"fig":"P21-06"},{"n":2,"title":"Draw a clue","text":"Draw a clue from the game on the envelope. What picture will help you find the right cards?","grownup":false,"optional":false,"fig":"P21-07"},{"n":3,"title":"Slide them in","text":"Slide the cards inside gently. If they bend or get stuck, stop and ask your grown-up for help.","grownup":false,"optional":false,"fig":"P21-08"},{"n":4,"title":"Close and return","text":"Fold the flap down without sticking it. Put the envelope in the game box, ready to play again.","grownup":false,"optional":false,"fig":"P21-09"}],"status":"live"},{"id":"P22","name":"Little Landing Pad","ages":"5–9","mins":5,"goal":"Give your cool drink a steady landing place.","start":"Wide, shallow jar lid","materials":[{"name":"Wide, shallow jar lid with a smooth rolled rim","qty":"1","optional":false,"grownup":false},{"name":"Lightweight, non-breakable cup","qty":"1, with its whole base fitting flat inside the lid","optional":false,"grownup":false},{"name":"Cool drinking water","qty":"1 normal drink for the child","optional":false,"grownup":false}],"suit":"Use a spare, wide, shallow lid with a smooth rolled rim, intact lining and no rust, sharp edges or dents. It must no longer be needed for its jar. An existing lightweight, non-breakable cup must fit with its whole base flat inside. No glass or hot drinks.","prep":"Wash the lid, dry it fully and inspect the rim and lining. Handle any original glass jar yourself and put it away. Place the lid rim-up on a flat, stable surface away from the edge. Test the empty cup: its whole base must rest flat without rocking or sliding. Skip this project if it is unstable. Supervise a cool drink and wipe the lid dry afterwards. Never cut, bend or hammer it. Use only items already owned. Keep it only if useful.","steps":[{"n":1,"title":"Grown-up checks","text":"Ask your grown-up to wash, dry and check the lid. They check that your empty cup fits steadily inside.","grownup":true,"optional":false,"fig":"P22-05"},{"n":2,"title":"Choose its place","text":"Put the lid rim-up on a flat part of your table, away from the edge.","grownup":false,"optional":false,"fig":"P22-06"},{"n":3,"title":"Try the empty cup","text":"Set your empty cup inside. Does its whole base sit flat? If it rocks or slides, stop and tell your grown-up.","grownup":false,"optional":false,"fig":"P22-07"},{"n":4,"title":"Use your landing pad","text":"With your grown-up, enjoy a cool drink. Place the cup gently on its landing pad between sips.","grownup":true,"optional":false,"fig":"P22-08"}],"status":"live"},{"id":"P25","name":"Plant Pal","ages":"5–9","mins":20,"goal":"Help your plant move house only when it needs more room.","start":"Plastic plant pot","materials":[{"name":"Clean plastic nursery pot with drainage holes","qty":"1, slightly larger than the current pot","optional":false,"grownup":false},{"name":"Existing plant needing repotting","qty":"1 plant in its current pot","optional":false,"grownup":true},{"name":"Suitable compost already available","qty":"Only enough for the base layer and gaps around the rootball","optional":false,"grownup":true},{"name":"Saucer or tray that fits the pot","qty":"1","optional":false,"grownup":false},{"name":"Water","qty":"The amount the grown-up advises for this plant","optional":false,"grownup":false},{"name":"Gardening gloves for the grown-up","qty":"1 suitable pair","optional":false,"grownup":true},{"name":"Small watering can","qty":"1 already owned","optional":false,"grownup":false},{"name":"Small garden trowel or compost scoop","qty":"1 already owned","optional":false,"grownup":true}],"suit":"Use an intact, clean nursery pot with smooth edges and existing drainage holes. It must be only slightly larger than the plant’s current pot. A grown-up must confirm the plant needs repotting and is suitable around children. Use an existing saucer, suitable compost and adult protective equipment.","prep":"Repot only when needed, using a slightly larger pot with drainage holes. Follow the compost label; work outside or with good ventilation. Wear gardening gloves and required protection already owned. Skip if unavailable. Handle all compost and roots yourself; avoid dust. Support the intact rootball at its former soil level, add compost underneath and around its sides, and firm gently. Do not bury the stem. Guide watering, let excess drain, then empty the saucer. Children avoid compost and roots; everyone washes hands afterwards.","steps":[{"n":1,"title":"Check the move","text":"Ask your grown-up if the plant needs more room. Point to the pot you think will fit.","grownup":true,"optional":false,"fig":"P25-09"},{"n":2,"title":"Find the way out","text":"Point to the drainage holes. Where will water go? Your grown-up adds compost with gardening gloves on. Keep your hands clear.","grownup":true,"optional":false,"fig":"P25-10"},{"n":3,"title":"Watch the plant move","text":"Watch your grown-up move the plant and fill the gaps. Does it sit at the same height as before?","grownup":true,"optional":false,"fig":"P25-11"},{"n":4,"title":"Care for your plant","text":"Water as your grown-up advises. Watch extra water drain; your grown-up empties the saucer. Everyone washes their hands.","grownup":true,"optional":false,"fig":"P25-12"}],"status":"live"},{"id":"P26","name":"Seed Library","ages":"5–9","mins":15,"goal":"Help your grown-up find the right seeds at planting time.","start":"Biscuit tin with lid","materials":[{"name":"Biscuit tin with lid","qty":"1 completely dry tin and matching lid","optional":false,"grownup":false},{"name":"Existing sealed seed packets in original packaging","qty":"The family’s current packets that fit with the lid closed","optional":false,"grownup":true},{"name":"Scrap-card pieces for dividers","qty":"2, already fitting below the tin’s rim","optional":false,"grownup":false},{"name":"Pencil","qty":"1","optional":false,"grownup":false}],"suit":"Use a clean, intact biscuit tin with a smooth rolled rim and a well-fitting lid, without rust or sharp edges. Tin and lid must be completely dry. Use only the family’s existing sealed seed packets in their original, labelled packaging and two scrap-card pieces that fit below the rim.","prep":"Wash, inspect and fully dry the tin and lid, including seams. Handle all seed packets yourself; keep them closed and retain their original labels and planting dates. Use the dates to choose 'plant soon' and 'plant later' groups. Select two existing card pieces that fit without cutting. Help label the child’s dividers. Pack the packets upright behind them, check the lid closes, and store according to packet instructions, out of children’s unsupervised reach. Do not buy seeds to fill the tin.","steps":[{"n":1,"title":"Rinse and dry","text":"Ask your grown-up to wash, check and fully dry the tin and lid. Seed packets must stay dry.","grownup":true,"optional":false,"fig":"P26-07"},{"n":2,"title":"Choose two groups","text":"Your grown-up reads the planting dates. Point to the group for each packet: plant soon or plant later.","grownup":true,"optional":false,"fig":"P26-08"},{"n":3,"title":"Make simple dividers","text":"Draw a sun on one divider and a calendar on the other. Ask your grown-up to add each group’s name.","grownup":false,"optional":false,"fig":"P26-09"},{"n":4,"title":"Pack for next time","text":"Watch your grown-up pack each group behind its divider and close the tin. Ask where it will stay until planting time.","grownup":true,"optional":false,"fig":"P26-10"}],"status":"live"},{"id":"P27","name":"Seedling Station","ages":"5–9","mins":10,"goal":"Catch the drips when your seedlings need a drink.","start":"Foil tray","materials":[{"name":"Clean foil tray","qty":"1 intact tray with a smooth rolled rim","optional":false,"grownup":false},{"name":"Existing seedling pots with drainage holes","qty":"3, fitting with gaps between them","optional":false,"grownup":false},{"name":"Water for normal plant care","qty":"Only the amount these plants need","optional":false,"grownup":false},{"name":"Small watering can","qty":"1 already owned","optional":false,"grownup":false},{"name":"Gardening gloves for the grown-up","qty":"1 suitable pair already owned, for any spilled compost","optional":false,"grownup":true}],"suit":"Use a clean, dry, intact foil tray with a smooth rolled rim, no tears or sharp edges, and a flat base. Three existing, child-suitable seedling pots must fit with gaps between them. The plants must need a drip tray; do not buy plants to fill it.","prep":"Clean and inspect every edge; reject damaged foil. Choose a steady, suitable place for the seedlings. Check that all three pots have drainage holes, clean outer surfaces and contained compost. Children hold only pot exteriors. Supervise normal watering when needed, never fill the tray as a reservoir. Move each pot separately before draining the tray; never carry it loaded. Remove excess water promptly, then replace the pots. Wear existing gardening gloves for any spilled compost; children keep away. Everyone washes hands afterwards.","steps":[{"n":1,"title":"Check the tray","text":"Ask your grown-up to clean the tray and check every edge. Do not use a torn or sharp tray.","grownup":true,"optional":false,"fig":"P27-06"},{"n":2,"title":"Choose a steady spot","text":"Put the empty tray on the steady surface your grown-up chooses. Leave it there while it holds the pots.","grownup":false,"optional":false,"fig":"P27-07"},{"n":3,"title":"Arrange the pots","text":"Hold the outside of each pot. Stand all three inside the tray with gaps between them. Keep your hands out of the compost.","grownup":false,"optional":false,"fig":"P27-08"},{"n":4,"title":"Catch normal watering drips","text":"When watering is needed, help water the plants, not the tray. Your grown-up removes extra water. Everyone washes their hands.","grownup":true,"optional":false,"fig":"P27-09"}],"status":"live"},{"id":"P28","name":"Story Hospital","ages":"5–9","mins":12,"goal":"Help a favourite story turn its page again.","start":"Family book with a small torn page","materials":[{"name":"Family-owned book with one small page tear","qty":"1","optional":false,"grownup":false},{"name":"Transparent paper-repair tape already owned","qty":"1 small strip, cut and applied by the grown-up","optional":false,"grownup":true},{"name":"Scissors for the grown-up","qty":"1 pair","optional":false,"grownup":true}],"suit":"Use an ordinary family-owned paper book, with permission, that already has one small, simple page tear. The book must have no mould, loose staples, damaged spine or detached pages. Suitable transparent paper-repair tape must already be available. Exclude library, school-owned, valuable and sentimental books.","prep":"Check that the small tear can be aligned without losing text or pictures. Follow the paper-repair tape’s instructions and cut one small strip yourself. Help the child lay the page flat and match the edges. Apply the strip while the child holds a corner clear of your work. Check that the page turns freely and remains readable. If it catches or the strip lifts, stop and reassess; do not add layers. Never damage a book to create this activity.","steps":[{"n":1,"title":"Find the patient","text":"Show your grown-up the small page tear. Ask whether this repair will help your family’s book.","grownup":true,"optional":false,"fig":"P28-05"},{"n":2,"title":"Match the edges","text":"Lay the page flat. Match the torn edges so the picture or words line up again.","grownup":false,"optional":false,"fig":"P28-06"},{"n":3,"title":"Mend together","text":"Hold a corner of the page still while your grown-up adds the small repair strip. Keep your fingers clear.","grownup":true,"optional":false,"fig":"P28-07"},{"n":4,"title":"Read it again","text":"Turn the page gently. Can you still see the story clearly? Enjoy reading your repaired book together.","grownup":false,"optional":false,"fig":"P28-08"}],"status":"live"},{"id":"P29","name":"Toy Sleepover","ages":"5–9","mins":8,"goal":"Give two soft toys a tidy home between adventures.","start":"Small spare cushion cover","materials":[{"name":"Small spare cushion cover with a working zip","qty":"1, empty","optional":false,"grownup":false},{"name":"Existing soft toys","qty":"2 small toys that fit loosely","optional":false,"grownup":false}],"suit":"Use a genuinely spare, small, clean, dry cushion cover with sound seams and a working zip. It must have no ties, tassels, loose trims or fastening parts. Two existing, age-appropriate soft toys without batteries or loose parts must fit loosely inside. The cover is only for toy storage.","prep":"Check the cover and zip; remove any cushion. Confirm that two toys fit loosely and the zip closes without force. Work on a table or floor. Help with the zip and keep fingers, fur and fabric clear; stop if it catches. Put the finished pack on a low shelf. Never put the cover over a head or body, in a bed or cot, or use the toy-filled cover as a pillow. Use only existing toys and an unneeded cover.","steps":[{"n":1,"title":"Choose the guests","text":"Choose two soft toys that need a tidy home. Which friends will share this space?","grownup":false,"optional":false,"fig":"P29-05"},{"n":2,"title":"Plan their places","text":"Lay the toys beside the cover. Will both fit with room to spare? Ask your grown-up to check.","grownup":false,"optional":false,"fig":"P29-06"},{"n":3,"title":"Pack gently","text":"Put the toys inside. Close the zip slowly, keeping fingers and fabric clear. If it catches, stop and ask your grown-up.","grownup":false,"optional":false,"fig":"P29-07"},{"n":4,"title":"Give it a home","text":"Put your toy pack on its low shelf. Your two friends are together, ready for the next adventure.","grownup":false,"optional":false,"fig":"P29-08"}],"status":"draft"}];